    'festival_registration_field_category_help' => '«Усі» додає поле до кожної категорії. Обрана категорія обмежує поле новими заявками цієї категорії; наявні заявки не перебудовуються.',
    'festival_registration_field_scope_help' => 'Створює одну відповідь на заявку, одну відповідь із позначенням реєстранта або окрему відповідь для кожного учасника. Зміна області діє лише для нових заявок.',
    'festival_registration_field_input_type_help' => 'Визначає елемент вводу для заявника та перевірку відповіді. Зміна також впливає на трактування поля в наявних заявках, тому не змінюйте тип після отримання відповідей.',
    'festival_registration_field_instructions_help' => 'Необов’язкова підказка під назвою поля, яка пояснює заявнику, що потрібно ввести або завантажити.',
    'festival_registration_field_pricing_mode_help' => 'За потреби розраховує рахунок із збереженої відповіді: фіксована сума за «Так», сума за кожну введену одиницю або ціна кожного обраного варіанта.',
    'festival_registration_field_amount_help' => 'Сума у валюті акаунта для режимів фіксованої ціни за «Так» і ціни за одиницю. Для цін варіантів використовуються суми біля кожного варіанта.',
    'festival_registration_field_max_file_size_help' => 'Найбільший дозволений розмір приватного файла в кілобайтах. Для типів поля без файла це налаштування не використовується.',
