    'festival_directions_page_copy' => 'Керуйте дисциплінами, які заявники можуть обрати для своїх виступів.',
    'festival_directions_help_title' => 'Що таке напрямок?',
    'festival_directions_help_copy' => 'Напрямок визначає дисципліну виступу, наприклад артистичний пілон або повітряну гімнастику. Кожна категорія має рівно один напрямок, а напрямок, який уже використовується, не можна деактивувати.',
    'festival_categories_page_copy' => 'Створюйте категорії, доступні заявникам, і зберігайте всі правила кожної категорії на окремій сторінці.',
    'festival_categories_help_title' => 'Що таке категорія?',
    'festival_categories_help_copy' => 'Категорія належить до одного напрямку й визначає склад, вік, тривалість, строк, сценарій і видимі заявнику умови. Зміни діють для заявок цієї категорії.',
    'festival_workflows_page_copy' => 'Налаштовуйте послідовні кроки, які має пройти кожна заявка категорії.',
    'festival_workflows_help_title' => 'Що таке сценарій реєстрації?',
    'festival_workflows_help_copy' => 'Сценарій — це впорядкований список кроків заявки, анкети, оплати й підсумку. Категорії обирають сценарій, а поля реєстрації та внески прив’язуються до його кроків.',
    'festival_registration_fields_page_copy' => 'Керуйте типізованими питаннями, приватними файлами й платними відповідями реєстрації.',
    'festival_registration_fields_help_title' => 'Що таке поле реєстрації?',
    'festival_registration_fields_help_copy' => 'Поле реєстрації збирає одну типізовану відповідь для заявки, реєстранта або учасника на конкретному кроці. Поточне налаштування копіюється до кожної нової заявки.',
    'festival_fees_page_copy' => 'Керуйте внесками за участь, які застосовуються до нових заявок.',
    'festival_fees_help_title' => 'Що таке внесок?',
    'festival_fees_help_copy' => 'Внесок прив’язаний до кроку сценарію й може діяти для всіх заявок або однієї категорії. Поточні ціни використовують валюту акаунта студії, а створені нарахування зберігають валюту транзакції.',
    'festival_content_page_copy' => 'Керуйте публічним контентом і матеріалами для інших розділів фестивалю.',
    'festival_content_help_title' => 'Де показується контент?',
    'festival_content_help_copy' => 'Активні публічні текстові блоки показуються на сторінці фестивалю. Документи доступні через захищене завантаження; блоки для порталу й персоналу та медіа, що не є обкладинкою, у поточній версії лише зберігаються для керування.',
    'festival_content_sections_copy' => 'Публічні блоки відображаються на сторінці фестивалю; інші рівні видимості зберігаються для майбутніх інтерфейсів.',
    'festival_documents_crud_copy' => 'Завантажуйте, замінюйте, активуйте та впорядковуйте документи. Під час заміни запис зберігається, а попередній файл безпечно видаляється.',
